INSERT INTO `command` (`name`, `security`, `help`) VALUES
    ('basic reload multipliers', 3, 'Syntax: .basic reload multipliers\n\nReads the per-creature damage, healing and health multipliers again without a restart. Health changes apply to creatures as they next spawn.\nIn game or on the server console. (Everland Ghostsong: src/cpp-basic/basic_rules.cpp)'),
    ('basic worldboss respawn', 2, 'Syntax: .basic worldboss respawn <spawn number>\n\nBrings a world boss back now, by its spawn number. The world bosses'' Lua countdown calls this when a boss is due.\nIn game or on the server console. (Everland Ghostsong: src/cpp-basic/basic_rules.cpp)'),
    ('basic worldboss status', 2, 'Syntax: .basic worldboss status\n\nLists every world boss spawn, its creature and whether it is alive or dead, and whether the world boss battle bonus is on.\nIn game or on the server console. (Everland Ghostsong: src/cpp-basic/basic_rules.cpp)'),
    ('buddy bed add', 2, 'Syntax: .buddy bed add <bed|cot|floor> [note]\n\nMarks the spot you stand on, facing the way you face, as a place buddies sleep, at that comfort (bed 3, cot 2, floor 1). The note is kept with it.\nIn game only. (Everland Ghostsong: modules/mod-buddies/src/buddies_beds.cpp)'),
    ('buddy bed link', 2, 'Syntax: .buddy bed link\n\nJoins the nearest sleeping spot to the next nearest, as one shared bed; both must be within 5 yards. A third spot is joined by standing between it and one of the pair.\nIn game only. (Everland Ghostsong: modules/mod-buddies/src/buddies_beds.cpp)'),
    ('buddy bed list', 2, 'Syntax: .buddy bed list\n\nLists the sleeping spots of the area you stand in, nearest first.\nIn game only. (Everland Ghostsong: modules/mod-buddies/src/buddies_beds.cpp)'),
    ('buddy bed remove', 2, 'Syntax: .buddy bed remove\n\nRemoves the nearest sleeping spot within 10 yards.\nIn game only. (Everland Ghostsong: modules/mod-buddies/src/buddies_beds.cpp)'),
    ('buddy bed unlink', 2, 'Syntax: .buddy bed unlink\n\nThe nearest sleeping spot within 5 yards stands alone again.\nIn game only. (Everland Ghostsong: modules/mod-buddies/src/buddies_beds.cpp)'),
    ('buddy explore', 0, 'Syntax: .buddy explore <pinwheel|paint|rooms|disc|mixed>\n\nChooses how your own buddies explore a town (the work is in buddies_explore.cpp): the pinwheel, least paint, the room orbit, the squished circle, or each buddy a different one in turn (mixed). Any player may set it for their own buddies.\nIn game only. (Everland Ghostsong: modules/mod-buddies/src/buddies_beds.cpp)'),
    ('buddy kit', 2, 'Syntax: .buddy kit <buddy name>\n\nGives a buddy in the world the kit''s gear for its level now, by its talent shape. What it wore is replaced.\nIn game or on the server console. (Everland Ghostsong: modules/mod-buddies/src/buddies_kit.cpp)'),
    ('buddy look', 2, 'Syntax: .buddy look <skin|face|hair|haircolor|beard> <number>\n\nChanges one part of Sargobras''s look until the server restarts. The client asks for a creature''s look when it first sees it: walk out of sight and back, or log out and in, to see the change.\nIn game or on the server console. (Everland Ghostsong: modules/mod-buddies/src/buddies_outfits.cpp)'),
    ('buddy record delete', 2, 'Syntax: .buddy record delete <number>\n\nDeletes one recording by the number the list shows.\nIn game only. (Everland Ghostsong: modules/mod-buddies/src/buddies_recorder.cpp)'),
    ('buddy record discard', 2, 'Syntax: .buddy record discard\n\nThrows away the recording in progress.\nIn game only. (Everland Ghostsong: modules/mod-buddies/src/buddies_recorder.cpp)'),
    ('buddy record list', 2, 'Syntax: .buddy record list\n\nLists the recordings of every ship stop near you, with their numbers.\nIn game only. (Everland Ghostsong: modules/mod-buddies/src/buddies_recorder.cpp)'),
    ('buddy record start', 2, 'Syntax: .buddy record start\n\nStarts recording your movements at a boat or zeppelin stop, for buddies to replay when they board or leave a ship.\nIn game only. (Everland Ghostsong: modules/mod-buddies/src/buddies_recorder.cpp)'),
    ('buddy record stop', 2, 'Syntax: .buddy record stop [note]\n\nEnds the recording, checks it is one boarding or one leaving at one stop of one ship''s route, and keeps it with the note.\nIn game only. (Everland Ghostsong: modules/mod-buddies/src/buddies_recorder.cpp)'),
    ('buddy town here', 2, 'Syntax: .buddy town here <radius>\n\nPlaces a town circle of that radius, in yards, where you stand: inside it buddies behave as in town. It is written to the world database at once.\nIn game only. (Everland Ghostsong: modules/mod-buddies/src/buddies_town_circles.cpp)'),
    ('buddy town remove', 2, 'Syntax: .buddy town remove\n\nRemoves the nearest town circle that was placed by hand.\nIn game only. (Everland Ghostsong: modules/mod-buddies/src/buddies_town_circles.cpp)'),
    ('buddy town show', 2, 'Syntax: .buddy town show\n\nDraws the nearest town circle in wisps standing on its edge, for 15 seconds.\nIn game only. (Everland Ghostsong: modules/mod-buddies/src/buddies_town_circles.cpp)'),
    ('buddy trace', 2, 'Syntax: .buddy trace <buddy name|off>\n\nStarts writing a log of what that buddy decides and does (it must be online). "off" stops every trace. The reply says where the lines go.\nIn game or on the server console. (Everland Ghostsong: modules/mod-buddies/src/buddies_trace.cpp)');
